// Command bench discovers (harness, provider, model) candidates from
// agent config and runs a corpus of small tasks to produce per-task metrics.
package main

import (
	"flag"
	"fmt"
	"os"

	"github.com/DocumentDrivenDX/fizeau/internal/productinfo"
)

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
	if len(args) == 0 {
		printUsage()
		return 2
	}

	switch args[0] {
	case "discover":
		return cmdDiscover(args[1:])
	case "run":
		return cmdRun(args[1:])
	case "report":
		return cmdReport(args[1:])
	case "profiles":
		return cmdProfiles(args[1:])
	case "evidence":
		return cmdEvidence(args[1:])
	case "matrix":
		return cmdMatrix(args[1:])
	case "matrix-aggregate":
		return cmdMatrixAggregate(args[1:])
	case "help", "-h", "--help":
		printUsage()
		return 0
	default:
		fmt.Fprintf(os.Stderr, "%s: unknown command %q\n", benchCommandName(), args[0])
		printUsage()
		return 2
	}
}

func benchCommandName() string {
	return productinfo.BinaryName + "-bench"
}

func printUsage() {
	fmt.Fprintf(os.Stderr, `Usage: %s <command> [flags]

Commands:
  discover   List discovered (harness, provider, model) candidates
  run        Run corpus against discovered candidates
  report     Render a results file as table, json, or markdown
  profiles   Manage v7 benchmark profiles (subcommand: list)
  evidence   Validate and append benchmark evidence records, including curated external imports
  matrix     Run the SD-010 harness/profile/task matrix
  matrix-aggregate
             Aggregate matrix cell reports into matrix.json, matrix.md, costs.json

Run '%s <command> -h' for command-specific flags.
`, benchCommandName(), benchCommandName())
}

// resolveWorkDir returns the working directory: --work-dir flag or cwd.
func resolveWorkDir(wd string) string {
	if wd != "" {
		return wd
	}
	d, err := os.Getwd()
	if err != nil {
		return "."
	}
	return d
}

// flagSet creates a FlagSet that writes to stderr with ContinueOnError.
func flagSet(name string) *flag.FlagSet {
	fs := flag.NewFlagSet(name, flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	return fs
}

package evidence

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/santhosh-tekuri/jsonschema/v5"
)

const (
	SchemaRelativePath = "scripts/benchmark/benchmark-evidence.schema.json"
	SchemaVersion      = "benchmark-evidence/v1"
)

// Validator loads and applies the benchmark evidence schema from a repo root.
type Validator struct {
	schema *jsonschema.Schema
}

// AppendReport summarizes the effect of an append operation.
type AppendReport struct {
	LedgerPath string
	Added      int
	Duplicates []string
}

// DuplicateRecordsError reports duplicate evidence records that were skipped.
type DuplicateRecordsError struct {
	RecordIDs []string
}

func (e *DuplicateRecordsError) Error() string {
	if e == nil || len(e.RecordIDs) == 0 {
		return "duplicate evidence records"
	}
	return fmt.Sprintf("duplicate evidence records: %s", strings.Join(e.RecordIDs, ", "))
}

// NewValidator compiles the benchmark evidence schema from repoRoot.
func NewValidator(repoRoot string) (*Validator, error) {
	schemaPath := filepath.Join(repoRoot, SchemaRelativePath)
	rawSchema, err := os.ReadFile(schemaPath)
	if err != nil {
		return nil, fmt.Errorf("read evidence schema %s: %w", schemaPath, err)
	}

	compiler := jsonschema.NewCompiler()
	compiler.AssertFormat = true
	if err := compiler.AddResource("benchmark-evidence.schema.json", bytes.NewReader(rawSchema)); err != nil {
		return nil, fmt.Errorf("add evidence schema: %w", err)
	}
	schema, err := compiler.Compile("benchmark-evidence.schema.json")
	if err != nil {
		return nil, fmt.Errorf("compile evidence schema: %w", err)
	}
	return &Validator{schema: schema}, nil
}

// ValidateFile validates one JSON or JSONL evidence file and returns the
// normalized records, including any generated record_id values.
func (v *Validator) ValidateFile(path string) ([]map[string]any, error) {
	rawRecords, err := loadRecords(path)
	if err != nil {
		return nil, err
	}

	normalized := make([]map[string]any, 0, len(rawRecords))
	for i, record := range rawRecords {
		doc, _, err := v.normalizeRecord(record)
		if err != nil {
			return nil, fmt.Errorf("%s line %d: %w", path, i+1, err)
		}
		normalized = append(normalized, doc)
	}
	return normalized, nil
}

// AppendLedger appends validated evidence records to a JSONL ledger.
func (v *Validator) AppendLedger(inputPath, ledgerPath string) (*AppendReport, error) {
	incoming, err := v.ValidateFile(inputPath)
	if err != nil {
		return nil, err
	}

	existing, err := loadLedgerRecords(ledgerPath)
	if err != nil {
		return nil, err
	}

	existingByFingerprint := make(map[string]string, len(existing))
	existingByID := make(map[string]string, len(existing))
	for _, record := range existing {
		fp, err := fingerprintRecord(record)
		if err != nil {
			return nil, err
		}
		id, _ := record["record_id"].(string)
		existingByFingerprint[fp] = id
		existingByID[id] = fp
	}

	var (
		additions  []map[string]any
		duplicates []string
	)
	seenNew := make(map[string]struct{}, len(incoming))
	for _, record := range incoming {
		fp, err := fingerprintRecord(record)
		if err != nil {
			return nil, err
		}
		id, _ := record["record_id"].(string)

		if existingID, ok := existingByFingerprint[fp]; ok {
			duplicates = append(duplicates, chooseDuplicateID(id, existingID))
			continue
		}
		if existingFP, ok := existingByID[id]; ok && existingFP != fp {
			return nil, fmt.Errorf("record_id %q already exists with different content", id)
		}
		if _, ok := seenNew[fp]; ok {
			duplicates = append(duplicates, id)
			continue
		}

		seenNew[fp] = struct{}{}
		additions = append(additions, record)
		existingByFingerprint[fp] = id
		existingByID[id] = fp
	}

	if len(additions) > 0 {
		if err := appendRecords(ledgerPath, additions); err != nil {
			return nil, err
		}
	}

	report := &AppendReport{
		LedgerPath: ledgerPath,
		Added:      len(additions),
		Duplicates: append([]string(nil), duplicates...),
	}
	if len(duplicates) > 0 {
		return report, &DuplicateRecordsError{RecordIDs: duplicates}
	}
	return report, nil
}

// StableRecordID returns the deterministic content-derived record_id for a
// record that omits record_id.
func StableRecordID(doc map[string]any) (string, error) {
	normalized, err := cloneDocument(doc)
	if err != nil {
		return "", err
	}
	delete(normalized, "record_id")
	sum := sha256.Sum256(mustMarshal(normalized))
	return hex.EncodeToString(sum[:]), nil
}

func (v *Validator) normalizeRecord(doc map[string]any) (map[string]any, string, error) {
	normalized, err := cloneDocument(doc)
	if err != nil {
		return nil, "", err
	}
	fp, err := fingerprintRecord(normalized)
	if err != nil {
		return nil, "", err
	}
	if id, _ := normalized["record_id"].(string); strings.TrimSpace(id) == "" {
		normalized["record_id"] = fp
	}
	if err := v.schema.Validate(normalized); err != nil {
		return nil, "", fmt.Errorf("schema validation failed: %w", err)
	}
	return normalized, fp, nil
}

func fingerprintRecord(doc map[string]any) (string, error) {
	normalized, err := cloneDocument(doc)
	if err != nil {
		return "", err
	}
	delete(normalized, "record_id")
	sum := sha256.Sum256(mustMarshal(normalized))
	return hex.EncodeToString(sum[:]), nil
}

func loadLedgerRecords(path string) ([]map[string]any, error) {
	info, err := os.Stat(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("stat ledger %s: %w", path, err)
	}
	if info.Size() == 0 {
		return nil, nil
	}
	return loadRecords(path)
}

func loadRecords(path string) ([]map[string]any, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read evidence file %s: %w", path, err)
	}

	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 {
		return nil, fmt.Errorf("evidence file %s is empty", path)
	}

	if record, err := decodeObject(trimmed); err == nil {
		return []map[string]any{record}, nil
	}

	lines := bytes.Split(trimmed, []byte("\n"))
	records := make([]map[string]any, 0, len(lines))
	for i, line := range lines {
		line = bytes.TrimSpace(line)
		if len(line) == 0 {
			continue
		}
		record, err := decodeObject(line)
		if err != nil {
			return nil, fmt.Errorf("%s line %d: %w", path, i+1, err)
		}
		records = append(records, record)
	}
	if len(records) == 0 {
		return nil, fmt.Errorf("evidence file %s contains no records", path)
	}
	return records, nil
}

func decodeObject(raw []byte) (map[string]any, error) {
	var doc map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil {
		return nil, err
	}
	return doc, nil
}

func cloneDocument(doc map[string]any) (map[string]any, error) {
	raw, err := json.Marshal(doc)
	if err != nil {
		return nil, fmt.Errorf("marshal evidence record: %w", err)
	}
	var out map[string]any
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, fmt.Errorf("clone evidence record: %w", err)
	}

package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/DocumentDrivenDX/fizeau/internal/benchmark/evidence"
)

func TestEvidenceValidateCommand(t *testing.T) {
	repoRoot := benchRepoRoot(t)
	valid := filepath.Join(repoRoot, "cmd", "bench", "testdata", "benchmark-evidence", "valid-record.jsonl")
	invalid := filepath.Join(repoRoot, "cmd", "bench", "testdata", "benchmark-evidence", "invalid-record.jsonl")

	if code, out := runBenchCLI(t, repoRoot, "evidence", "validate", "--work-dir", repoRoot, valid); code != 0 {
		t.Fatalf("validate valid fixture exit=%d output=%s", code, out)
	}

	if code, out := runBenchCLI(t, repoRoot, "evidence", "validate", "--work-dir", repoRoot, invalid); code == 0 {
		t.Fatalf("validate invalid fixture unexpectedly succeeded: %s", out)
	} else if !strings.Contains(out, "artifact_sha256") && !strings.Contains(out, "evidence validate") {
		t.Fatalf("validate invalid fixture error missing useful context: %s", out)
	}
}

func TestEvidenceAppendGeneratesStableRecordID(t *testing.T) {
	repoRoot := benchRepoRoot(t)
	input := filepath.Join(repoRoot, "cmd", "bench", "testdata", "benchmark-evidence", "append-input.jsonl")
	ledger := filepath.Join(t.TempDir(), "ledger.jsonl")

	if code, out := runBenchCLI(t, repoRoot, "evidence", "append", "--work-dir", repoRoot, "--in", input, "--ledger", ledger); code != 0 {
		t.Fatalf("append exit=%d output=%s", code, out)
	}

	record := readSingleJSONLRecord(t, ledger)
	doc := readSingleJSONRecord(t, input)
	wantID, err := evidence.StableRecordID(doc)
	if err != nil {
		t.Fatalf("StableRecordID: %v", err)
	}
	if got := mustStringField(t, record, "record_id"); got != wantID {
		t.Fatalf("ledger record_id = %q, want %q", got, wantID)
	}
}

func TestEvidenceAppendDetectsDuplicates(t *testing.T) {
	repoRoot := benchRepoRoot(t)
	input := filepath.Join(repoRoot, "cmd", "bench", "testdata", "benchmark-evidence", "append-input.jsonl")
	ledger := filepath.Join(t.TempDir(), "ledger.jsonl")

	validator, err := evidence.NewValidator(repoRoot)
	if err != nil {
		t.Fatalf("NewValidator: %v", err)
	}

	report, err := validator.AppendLedger(input, ledger)
	if err != nil {
		t.Fatalf("first append: %v", err)
	}
	if report.Added != 1 {
		t.Fatalf("first append added %d records, want 1", report.Added)
	}

	report, err = validator.AppendLedger(input, ledger)
	var dupErr *evidence.DuplicateRecordsError
	if !errors.As(err, &dupErr) {
		t.Fatalf("second append error = %v, want DuplicateRecordsError", err)
	}
	if report == nil || len(report.Duplicates) == 0 {
		t.Fatalf("second append did not report duplicates: %#v", report)
	}

	raw, err := os.ReadFile(ledger)
	if err != nil {
		t.Fatalf("read ledger: %v", err)
	}
	if got := len(bytes.Split(bytes.TrimSpace(raw), []byte("\n"))); got != 1 {
		t.Fatalf("ledger line count = %d, want 1", got)
	}
}

